using ModelContextProtocol;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";

    [McpServerTool, Description("Returns the current server UTC time.")]
    public static string GetServerTime()
        => $"Server time: {DateTime.UtcNow:O}";
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        Uri = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the current application configuration data.",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        return """
        {
            "environment": "production",
            "version": "1.0.0",
            "features": {
                "darkMode": true,
                "notifications": true,
                "maxRetries": 3
            },
            "endpoints": {
                "api": "https://api.example.com",
                "cdn": "https://cdn.example.com"
            }
        }
        """;
    }

    [McpServerResource(
        Uri = "config://app/health",
        Name = "Health Status",
        Description = "Returns the server health status.",
        MimeType = "application/json")]
    public static string GetHealthStatus()
    {
        return $$"""
        {
            "status": "healthy",
            "uptime": "{{Environment.TickCount64 / 1000}}s",
            "timestamp": "{{DateTime.UtcNow:O}}"
        }
        """;
    }
}

